// /money/explain: one disclosed-money flow, explained from the data alone.
//
// Every figure here is summed from the year cells of the money graph
// (/graph/money*.json), the party returns' own totals (/graph/aec-extras.json)
// or the bill register (/bills/index.json and /bills/<key>.json), and every
// sentence is a template filled from those sums. Nothing is generated by a
// model and nothing calls a model route: a reader who wants an answer in words
// from the record is linked to Ask, which says so itself.
//
// The address carries graph node IDs, never names. A donor OPAX does not name
// (donor-entity.js, failing closed) is never shown, never echoed and never left
// in the address bar: its flow is rewritten to the neutral "Donors not named"
// aggregate for the same recipient before anything renders. Unknown IDs and
// repeated keys fail closed rather than widening, as the ledger's do.
//
// Styles: money-explain.css, loaded with the module.

import { donorNameWithheld, loadDonorViewIndex, unnamedDonorLabel, donorsNotNamedDetail } from './donor-views.js?v=77470b1d26';
import { sourceLineHTML, partyLabelHTML } from './labels.js?v=c6bf994ef7';
import { subjectUrl } from './canonical-urls.js?v=225d5915ea';
import { shortMoney, shortDate } from './format.js?v=9fcab43d8d';

const STYLE_HREF = '/money-explain.css?v=7738084ea5';

// --- sources -------------------------------------------------------------------
// The pages behind the "what the record does and doesn't show" notes. Each was
// read on 12 Oct 2026; the wording below stays inside what they say.

export const SOURCES = {
  aecRegister: { label: 'AEC Transparency Register', href: 'https://transparency.aec.gov.au/' },
  aecReceipts: { label: 'AEC detailed receipts (filter by year, recipient and receipt type)', href: 'https://transparency.aec.gov.au/AnnualDetailedReceipts' },
  aecPartyReturns: { label: 'AEC political party annual returns', href: 'https://transparency.aec.gov.au/AnnualPoliticalParty' },
  aecThresholds: { label: 'AEC: disclosure threshold by year', href: 'https://www.aec.gov.au/Parties_and_Representatives/public_funding/threshold.htm' },
  aecOldThreshold: { label: 'AEC advice: the threshold moved from $1,500 on 8 December 2005', href: 'https://aec.gov.au/Parties_and_Representatives/compliance/AEC_Advice/twu.htm' },
  aecLodging: { label: 'AEC guide: annual returns due 16 weeks after 30 June', href: 'https://www.aec.gov.au/Parties_and_Representatives/financial_disclosure/guides/political-parties/annual.htm' },
  aecPublished2026: { label: 'AEC: 2024–25 returns published 2 February 2026', href: 'https://www.aec.gov.au/media/2026/01-29.htm' },
  aecReceiptKinds: { label: 'AEC: receipts include gifts and other receipts', href: 'https://aec.gov.au/media/media-releases/2019/02-01.htm' },
  aecBranches: { label: 'AEC: parties and their state branches lodge annual returns', href: 'https://aec.gov.au/media/media-releases/2019/02-01.htm' },
  aecPublished2019: { label: 'AEC: 2017–18 returns published 1 February 2019', href: 'https://aec.gov.au/media/media-releases/2019/02-01.htm' },
  aecReform: { label: 'AEC: funding and disclosure changes from 1 January 2027', href: 'https://aec.gov.au/FADReform/faqs.htm' },
  aecReformDate: { label: 'AEC: reforms commence 1 January 2027', href: 'https://www.aec.gov.au/FAQs/disclosure-legislation-changes.htm' },
};

/** The federal disclosure threshold by financial year (the year it starts), as
 *  the AEC lists it. Before 8 December 2005 it was $1,500. */
const FEDERAL_THRESHOLDS = {
  2006: 10300, 2007: 10500, 2008: 10900, 2009: 11200, 2010: 11500, 2011: 11900, 2012: 12100,
  2013: 12400, 2014: 12800, 2015: 13000, 2016: 13200, 2017: 13500, 2018: 13800, 2019: 14000,
  2020: 14300, 2021: 14500, 2022: 15200, 2023: 16300, 2024: 16900, 2025: 17300, 2026: 17300,
};

/** The threshold that applied to one federal financial year, in words. */
export function federalThreshold(year) {
  const dollars = (n) => `$${n.toLocaleString('en-AU')}`;
  if (year < 2005) return '$1,500';
  if (year === 2005) return '$1,500 to 7 December 2005, then more than $10,000';
  if (year === 2026) return 'more than $17,300 to 31 December 2026, then more than $5,000 from 1 January 2027';
  if (FEDERAL_THRESHOLDS[year]) return `more than ${dollars(FEDERAL_THRESHOLDS[year])}`;
  return '';
}

/** What each register calls a line, from its own export's description. */
const STATE_LINES = {
  qld: { noun: 'gift', register: 'gifts to registered political parties' },
  vic: { noun: 'donation', register: 'donations to registered political parties' },
  tas: { noun: 'donation', register: 'reportable political donations' },
};

const FEDERAL_META = { jurisdictionLabel: 'Federal', commission: 'Australian Electoral Commission', sourceShort: 'AEC returns', source_url: 'https://transparency.aec.gov.au/' };
export const JURISDICTIONS = ['federal', 'qld', 'vic', 'tas'];
/** A presentation rule, not a safeguard: when every giver in a view is a donor
 *  OPAX doesn't name and there are fewer than this many, the page gives the
 *  total and the count only. (The served money files still carry each such
 *  donor's figures under a placeholder; what is withheld is the name.) */
export const AGGREGATE_FLOOR = 5;
/** The industry tag the graphs give donors recorded as people: the not-named group, never an industry view. */
const PERSON_TAGS = new Set(['individual', 'individuals']);
export const EXPLAIN_KEYS = ['jur', 'from', 'to', 'industry', 'donors'];

// --- small helpers ---------------------------------------------------------------

const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fold = (value) => String(value ?? '').normalize('NFKC').replace(/[‘’ʼ`]/g, "'").replace(/[_\s]+/g, ' ').trim().toLowerCase();
const plural = (n, one, many = `${one}s`) => `${Number(n).toLocaleString('en-AU')} ${n === 1 ? one : many}`;
const possessive = (name) => (/s$/i.test(name) ? `${name}’` : `${name}’s`);
const pct = (part, whole) => (whole > 0 ? (part / whole) * 100 : 0);
/** "12%", "0.4%", "under 0.1%": a share as a reader says it. */
export function pctText(part, whole) {
  const p = pct(part, whole);
  if (p <= 0) return '0%';
  if (p < 0.1) return 'under 0.1%';
  return p < 10 ? `${p.toFixed(1).replace(/\.0$/, '')}%` : `${Math.round(p)}%`;
}
const isDonation = (edge) => edge && !edge.grant && !edge.flow;
const isWithheldNode = (node, index) => node?.kind === 'donor' && (/^donor:withheld-\d+$/.test(node.id) || donorNameWithheld(index, node.label));

/** "2018–19": a financial year from the year it starts. */
export const fyLabel = (year) => `${year}–${String((Number(year) + 1) % 100).padStart(2, '0')}`;

/** The year a sentence names, with the federal file's election returns, which
 *  it files under their polling year, said where they can sit. */
export function yearPhrase(year, jur, electionYears = []) {
  return jur === 'federal' && electionYears.includes(Number(year)) ? `${fyLabel(year)} (with the ${year} election returns)` : fyLabel(year);
}

/** An industry key as a name: "fossil_fuels" is "Fossil fuels", "mining & energy" "Mining & energy". */
export function industryName(key) {
  const k = String(key || '');
  if (!k) return 'Industry not recorded';
  if (['individual', 'individuals'].includes(k.toLowerCase())) return 'Industry not recorded';
  const words = k.replace(/_/g, ' ');
  return words.charAt(0).toUpperCase() + words.slice(1);
}

/** Every donation edge's year cells summed: a total that a year window can re-sum. */
export function sumEdges(edges) {
  const years = new Map();
  let total = 0, count = 0;
  const undated = [0, 0];
  for (const edge of edges) {
    total += Number(edge.total) || 0;
    count += Number(edge.count) || 0;
    for (const [key, cell] of Object.entries(edge.byYear || {})) {
      const year = Number(key);
      if (!Number.isInteger(year)) continue;
      const old = years.get(year) || [0, 0];
      years.set(year, [old[0] + (Number(cell?.[0]) || 0), old[1] + (Number(cell?.[1]) || 0)]);
    }
    undated[0] += Number(edge.undated?.[0]) || 0;
    undated[1] += Number(edge.undated?.[1]) || 0;
  }
  return { total, count, years, undated };
}

// --- the address ----------------------------------------------------------------

/** The jurisdiction an address names, or null when it names one OPAX does not serve. */
export function explainJurisdiction(params) {
  const values = params.getAll('jur');
  if (values.length > 1) return null;
  const jur = values[0] || 'federal';
  return JURISDICTIONS.includes(jur) ? jur : null;
}

/**
 * Read /money/explain's query against one jurisdiction's graph.
 * - `from` is a donor node ID, `to` a party node ID, `industry` an industry or
 *   cluster key the graph uses, `donors=unnamed` the not-named aggregate.
 * - A `from` naming a donor OPAX withholds becomes `donors=unnamed` for the
 *   same recipient (`withheld: true`), so the address never keeps it.
 * - Unknown IDs, repeated keys and mixed subjects fail closed. Other keys are
 *   ignored and dropped from the canonical address.
 * @returns {{ok: true, state: object, withheld: boolean, empty?: boolean} | {ok: false, error: string}}
 */
export function parseExplainParams(params, graph, index) {
  const fail = (error) => ({ ok: false, error });
  for (const key of EXPLAIN_KEYS) if (params.getAll(key).length > 1) return fail('An explanation takes one value for each filter.');
  const jur = explainJurisdiction(params);
  if (!jur) return fail('OPAX does not hold money data for that jurisdiction.');
  const nodes = graph?.nodes || [];
  const get = (key) => (params.get(key) || '').trim();
  const fromId = get('from'), toId = get('to'), industry = get('industry'), donors = get('donors');
  const state = { jur };
  if (!fromId && !toId && !industry && !donors) return { ok: true, state, withheld: false, empty: true };
  if ([fromId, industry, donors].filter(Boolean).length > 1) return fail('An explanation follows one giver at a time.');
  if (toId) {
    const party = nodes.find((n) => n.kind === 'party' && n.id === toId);
    if (!party) return fail('That recipient is not in OPAX’s money data.');
    state.to = party.id;
  }
  if (donors) {
    if (donors !== 'unnamed') return fail('That filter is not one OPAX supports.');
    state.unnamed = true;
    return { ok: true, state, withheld: false };
  }
  if (industry) {
    const known = nodes.some((n) => n.kind === 'donor' && (n.industry === industry || n.group === industry));
    if (!known) return fail('That industry is not in OPAX’s money data.');
    if (PERSON_TAGS.has(industry)) {
      const out = { jur, unnamed: true };
      if (state.to) out.to = state.to;
      return { ok: true, state: out, withheld: true };
    }
    state.industry = industry;
    return { ok: true, state, withheld: false };
  }
  if (fromId) {
    const donor = nodes.find((n) => n.kind === 'donor' && n.id === fromId);
    if (!donor) return fail('That donor is not in OPAX’s money data.');
    if (isWithheldNode(donor, index)) {
      const out = { jur, unnamed: true };
      if (state.to) out.to = state.to;
      return { ok: true, state: out, withheld: true };
    }
    state.from = donor.id;
  }
  return { ok: true, state, withheld: false };
}

/** The one address for a state: keys in a fixed order, federal left implicit. */
export function explainPath(state) {
  const p = new URLSearchParams();
  if (state.jur && state.jur !== 'federal') p.set('jur', state.jur);
  if (state.from) p.set('from', state.from);
  if (state.industry) p.set('industry', state.industry);
  if (state.unnamed) p.set('donors', 'unnamed');
  if (state.to) p.set('to', state.to);
  const q = p.toString();
  return q ? `/money/explain?${q}` : '/money/explain';
}

/**
 * The address for a page or map "Explain" action that names its two sides by
 * label ({kind, from, to, jurisdiction}), as the money map's cards do. A label
 * OPAX withholds resolves to the not-named aggregate; one the graph lacks gives null.
 */
export function explainHrefFor(detail, graph, index) {
  if (!detail || !['industry', 'donor', 'party'].includes(detail.kind)) return null;
  const jur = JURISDICTIONS.includes(detail.jurisdiction) ? detail.jurisdiction : 'federal';
  const nodes = graph?.nodes || [];
  const byLabel = (kind, label) => {
    const key = fold(label);
    return key ? nodes.find((n) => n.kind === kind && fold(n.label) === key) || null : null;
  };
  const state = { jur };
  const partyLabel = detail.kind === 'party' ? (detail.to || detail.from) : detail.to;
  if (partyLabel) {
    const party = byLabel('party', partyLabel);
    if (!party) return null;
    state.to = party.id;
  }
  if (detail.kind === 'donor') {
    const donor = byLabel('donor', detail.from);
    if (donor && !isWithheldNode(donor, index)) state.from = donor.id;
    // A withheld donor, or a name the graph lacks that would not pass as an
    // organisation: the neutral aggregate. Never the name.
    else if (donor || donorNameWithheld(index, String(detail.from || ''))) state.unnamed = true;
    else return null;
  } else if (detail.kind === 'industry') {
    const key = fold(detail.from);
    const hit = nodes.find((n) => n.kind === 'donor' && (fold(n.industry) === key || fold(n.group) === key));
    if (!hit) return null;
    const industry = fold(hit.industry) === key ? hit.industry : hit.group;
    if (PERSON_TAGS.has(industry)) state.unnamed = true;
    else state.industry = industry;
  } else if (!state.to) return null;
  return explainPath(state);
}

// --- the flow -------------------------------------------------------------------

/** Party returns' own headline receipts by financial year, from aec-extras. */
function partyReturns(aec, partyLabel) {
  const rows = aec?.parties?.[partyLabel]?.returns;
  const out = new Map();
  for (const row of Array.isArray(rows) ? rows : []) {
    const year = Number(String(row?.[0] || '').slice(0, 4));
    if (!Number.isInteger(year)) continue;
    out.set(year, {
      receipts: Math.max(0, Number(row[1]) || 0), branches: Number(row[4]) || 0,
      donations: Math.max(0, Number(row[5]) || 0), other: Math.max(0, Number(row[6]) || 0),
      publicFunding: Math.max(0, Number(row[7]) || 0),
    });
  }
  return out;
}

/**
 * Everything the page says about one state, computed once. Withheld donors
 * stay in totals and counts and never in a named row.
 */
export function resolveFlow(state, graph, index, { aec = null, electionYears = [] } = {}) {
  const nodes = graph.nodes || [];
  const byId = new Map(nodes.map((n) => [n.id, n]));
  const donation = (graph.edges || []).filter(isDonation);
  const party = state.to ? byId.get(state.to) : null;
  const donor = state.from ? byId.get(state.from) : null;
  const meta = { ...(state.jur === 'federal' ? FEDERAL_META : {}), ...(graph.meta || {}) };
  const inIndustry = (n) => n?.kind === 'donor' && (n.industry === state.industry || n.group === state.industry);
  const withheld = (n) => isWithheldNode(n, index);

  let kind, givers;
  if (state.unnamed) { kind = 'unnamed'; givers = (e) => withheld(byId.get(e.source)); }
  else if (donor) { kind = party ? 'pair' : 'donor'; givers = (e) => e.source === donor.id; }
  else if (state.industry) { kind = 'industry'; givers = (e) => inIndustry(byId.get(e.source)); }
  else { kind = 'party'; givers = (e) => byId.get(e.source)?.kind === 'donor'; }
  const context = donation.filter(givers); // the givers' money to every party
  const edges = party ? context.filter((e) => e.target === party.id) : context;
  const sums = sumEdges(edges);
  const dated = [...sums.years].filter(([, cell]) => cell[0] > 0).sort((a, b) => a[0] - b[0]);
  const peak = dated.reduce((best, row) => (!best || row[1][0] > best[1][0] ? row : best), null);
  const last = dated[dated.length - 1] || null;

  // Who gave, organisations by name, the rest as one aggregate.
  const giverTotals = new Map();
  for (const e of edges) {
    const row = giverTotals.get(e.source) || { node: byId.get(e.source), total: 0, count: 0 };
    row.total += Number(e.total) || 0; row.count += Number(e.count) || 0;
    giverTotals.set(e.source, row);
  }
  const named = [], unnamed = { donors: 0, total: 0, count: 0 };
  for (const row of giverTotals.values()) {
    if (!row.node) continue;
    if (withheld(row.node)) { unnamed.donors += 1; unnamed.total += row.total; unnamed.count += row.count; }
    else named.push(row);
  }
  named.sort((a, b) => b.total - a.total);

  // Where it went: the same givers' money by party.
  const partyTotals = new Map();
  for (const e of context) partyTotals.set(e.target, (partyTotals.get(e.target) || 0) + (Number(e.total) || 0));
  const parties = [...partyTotals].map(([id, total]) => ({ node: byId.get(id), total }))
    .filter((r) => r.node?.kind === 'party').sort((a, b) => b.total - a.total);
  const contextTotal = parties.reduce((s, r) => s + r.total, 0);

  // Industries behind a party's money (party and not-named views).
  const industryTotals = new Map();
  for (const e of edges) {
    const n = byId.get(e.source);
    const key = n?.group || n?.industry || 'other';
    industryTotals.set(key, (industryTotals.get(key) || 0) + (Number(e.total) || 0));
  }
  const industries = [...industryTotals].map(([key, total]) => ({ key, total })).sort((a, b) => b.total - a.total);

  // The flow as a share of the recipient's money for the same years.
  let recipientShare = null;
  if (party && dated.length) {
    const first = dated[0][0], lastYear = last[0];
    const inSpan = (y) => y >= first && y <= lastYear;
    const flowInSpan = dated.reduce((s, [y, c]) => s + (inSpan(y) ? c[0] : 0), 0);
    const returns = state.jur === 'federal' ? partyReturns(aec, party.label) : new Map();
    if (returns.size) {
      let receipts = 0, held = 0, branches = 0, donations = 0, other = 0, publicFunding = 0;
      for (const [y, r] of returns) if (inSpan(y)) { receipts += r.receipts; held += 1; donations += r.donations; other += r.other; publicFunding += r.publicFunding; }
      const latestReturn = [...returns].filter(([y]) => inSpan(y)).sort((a, b) => b[0] - a[0])[0];
      branches = latestReturn?.[1].branches || 0;
      // A share over 100% would mean the two files count different things in
      // those years; it is not shown rather than shown wrong.
      if (receipts > 0 && flowInSpan <= receipts) recipientShare = {
        basis: 'returns', amount: flowInSpan, whole: receipts, first, last: lastYear, years: lastYear - first + 1, held,
        branches, branchesYear: latestReturn?.[0] ?? null, donations, other, publicFunding,
      };
    } else {
      const partySums = sumEdges([{ byYear: party.byYear || {} }]);
      let whole = 0;
      for (const [y, c] of partySums.years) if (inSpan(y)) whole += c[0];
      if (whole > 0 && flowInSpan <= whole) recipientShare = { basis: 'file', amount: flowInSpan, whole, first, last: lastYear, years: lastYear - first + 1 };
    }
  }
  // The flow as a share of a named organisation's disclosed giving.
  let donorShare = null;
  if (donor && party) {
    const whole = context.reduce((s, e) => s + (Number(e.total) || 0), 0);
    if (whole > 0) donorShare = { amount: sums.total, whole, parties: parties.length };
  }

  const flow = {
    state, kind, jur: state.jur, meta, graph, electionYears,
    donor, party, industry: state.industry || (donor ? donor.industry : null),
    edges, context, parties, contextTotal, named, unnamed, industries,
    total: sums.total, count: sums.count, years: sums.years, undated: sums.undated,
    dated, firstYear: dated[0]?.[0] ?? null, lastYear: last?.[0] ?? null,
    peak: peak ? { year: peak[0], amount: peak[1][0], count: peak[1][1] } : null,
    latest: last ? { year: last[0], amount: last[1][0], count: last[1][1] } : null,
    recipientShare, donorShare, aecLatest: state.jur === 'federal' ? aec?.meta?.latest_year || null : null,
    coarse: false,
  };
  // The floor follows who is in the view, not the address that asked for it:
  // a not-named group, an industry or a party whose givers are all donors OPAX
  // doesn't name, fewer than the floor, gets its total and count only.
  if (!named.length && unnamed.donors > 0 && unnamed.donors < AGGREGATE_FLOOR) Object.assign(flow, {
    coarse: true, years: new Map(), undated: [0, 0], dated: [], firstYear: null, lastYear: null,
    peak: null, latest: null, recipientShare: null, industries: [], parties: [], contextTotal: 0,
  });
  return flow;
}

/**
 * Two or three other flows of a similar kind, chosen by a stated rule, each
 * linking to its own explanation. Organisations by name; not-named donors
 * only as their aggregate. Never related to the flow; only beside it.
 */
export function comparableFlows(flow, index, limit = 3) {
  const { graph, state } = flow;
  if (flow.coarse && flow.kind === 'industry') return { rule: '', rows: [] };
  const byId = new Map(graph.nodes.map((n) => [n.id, n]));
  const donation = graph.edges.filter(isDonation);
  const withheld = (n) => isWithheldNode(n, index);
  const size = (t) => Math.abs(Math.log10(Math.max(t, 1)) - Math.log10(Math.max(flow.total, 1)));
  const out = [];
  if (flow.kind === 'donor') {
    const ind = flow.donor.industry;
    const totals = new Map();
    for (const e of donation) {
      const d = byId.get(e.source);
      if (d?.kind !== 'donor' || d.id === flow.donor.id || d.industry !== ind || withheld(d)) continue;
      const row = totals.get(d.id) || { d, total: 0, count: 0 };
      row.total += Number(e.total) || 0; row.count += Number(e.count) || 0;
      totals.set(d.id, row);
    }
    const rows = [...totals.values()].sort((a, b) => size(a.total) - size(b.total)).slice(0, limit)
      .map((r) => ({ label: r.d.label, total: r.total, count: r.count, href: explainPath({ jur: state.jur, from: r.d.id }) }));
    return { rule: `Other organisations OPAX tags as ${industryName(ind).toLowerCase()}, closest in size`, rows };
  }
  if (flow.kind === 'pair') {
    const ind = flow.donor.industry;
    const pool = donation.filter((e) => e.source !== flow.donor.id && (!flow.party || e.target === flow.party.id))
      .map((e) => ({ e, d: byId.get(e.source), p: byId.get(e.target) }))
      .filter((r) => r.d?.kind === 'donor' && r.p?.kind === 'party' && !withheld(r.d));
    const pick = (rows) => rows.sort((a, b) => size(a.e.total) - size(b.e.total));
    const sameIndustry = pick(pool.filter((r) => r.d.industry === ind));
    const rows = sameIndustry.slice(0, limit);
    const rule = `Other organisations OPAX tags as ${industryName(ind).toLowerCase()} giving to ${flow.party.label}, closest in size`;
    if (rows.length < 2) {
      for (const r of pick(pool.filter((x) => x.d.industry !== ind))) { if (rows.length >= Math.min(limit, 2)) break; rows.push(r); }
    }
    const seen = new Set();
    for (const r of rows) {
      if (seen.has(r.d.id)) continue;
      seen.add(r.d.id);
      out.push({ label: r.d.label, total: r.e.total, count: r.e.count, first: r.e.firstYear, last: r.e.lastYear,
        href: explainPath({ jur: state.jur, from: r.d.id, to: r.p.id }), sameIndustry: r.d.industry === ind });
    }
    return { rule: rows.some((r) => r.d.industry !== ind) ? `${rule}; then any industry` : rule, rows: out.slice(0, limit) };
  }
  if (flow.kind === 'party') {
    const rows = graph.nodes.filter((n) => n.kind === 'party' && n.id !== flow.party.id).map((p) => {
      const s = sumEdges(donation.filter((e) => e.target === p.id && byId.get(e.source)?.kind === 'donor'));
      return { label: `${p.label}: all donors on the map`, total: s.total, count: s.count, href: explainPath({ jur: state.jur, to: p.id }) };
    }).filter((r) => r.total > 0).sort((a, b) => b.total - a.total).slice(0, limit);
    return { rule: 'The other parties in this file, largest first', rows };
  }
  if (flow.kind === 'unnamed') {
    const rows = graph.nodes.filter((n) => n.kind === 'party' && n.id !== flow.party?.id).map((p) => {
      const s = sumEdges(donation.filter((e) => e.target === p.id && withheld(byId.get(e.source))));
      return { label: `Donors not named → ${p.label}`, total: s.total, count: s.count, href: explainPath({ jur: state.jur, unnamed: true, to: p.id }) };
    }).filter((r) => r.total > 0).sort((a, b) => b.total - a.total).slice(0, flow.party ? limit : 0);
    return { rule: 'Donors not named, to the other parties in this file, largest first', rows };
  }
  // An industry: the same industry to the other parties, or (all parties) the other industries.
  if (flow.party) {
    const rows = flow.parties.filter((r) => r.node.id !== flow.party.id).slice(0, limit)
      .map((r) => ({ label: `${industryName(state.industry)} → ${r.node.label}`, total: r.total, href: explainPath({ jur: state.jur, industry: state.industry, to: r.node.id }) }));
    return { rule: `${industryName(state.industry)} donors’ money to the other parties, largest first`, rows };
  }
  const groups = new Map();
  for (const e of donation) {
    const n = byId.get(e.source);
    if (n?.kind !== 'donor' || !n.group || n.group === state.industry || n.industry === state.industry || ['individuals', 'other'].includes(n.group)) continue;
    groups.set(n.group, (groups.get(n.group) || 0) + (Number(e.total) || 0));
  }
  const rows = [...groups].map(([key, total]) => ({ key, total })).sort((a, b) => size(a.total) - size(b.total)).slice(0, limit)
    .map((r) => ({ label: industryName(r.key), total: r.total, href: explainPath({ jur: state.jur, industry: r.key }) }));
  return { rule: 'Other industries on the map, closest in size', rows };
}

// --- parliament, for context --------------------------------------------------------
// Bills whose own titles name the industry: a match a reader can check by
// reading the title. Industries with no such words get no section at all.

/** The phrases a bill's title must contain, whole, to sit beside an industry:
 *  the industry's own name or the regime that regulates it. A loose word
 *  ("housing", "media", "bank", "gas") is not enough; an industry left out
 *  gets no section at all. */
export const BILL_WORDS = {
  gambling: ['gambling', 'wagering'],
  tobacco: ['tobacco'],
  alcohol: ['alcohol', 'liquor'],
  mining: ['mining', 'minerals resource rent tax', 'minerals exploration'],
  fossil_fuels: ['coal', 'offshore petroleum', 'petroleum and other fuels'],
  pharmacy: ['pharmaceutical benefits', 'pharmacy', 'pharmacies'],
  health: ['private health insurance'],
  telecom: ['telecommunications'],
  media: ['news media', 'broadcasting', 'media reform'],
  finance: ['banking', 'bank levy', 'financial services'],
  unions: ['fair work', 'registered organisations', 'workplace relations', 'industrial relations'],
  property: ['housing affordability', 'housing supply', 'housing measures', 'building and construction industry'],
  agriculture: ['agriculture', 'agricultural'],
  waste_management: ['waste'],
};
/** Titles that carry an industry phrase but are about something else. */
const BILL_EXCLUDE = {
  telecom: ['interception', 'production orders', 'assistance and access'],
  media: ['australian broadcasting corporation'],
};
const GROUP_INDUSTRIES = {
  'mining & energy': ['mining', 'fossil_fuels'], 'health & pharma': ['health', 'pharmacy'],
  'media & tech': ['media', 'telecom'], 'tobacco & alcohol': ['tobacco', 'alcohol'],
};
const industriesFor = (key) => GROUP_INDUSTRIES[key] || [key];
/** The title phrases that tie an industry key (or a map cluster) to bills, or []. */
export function billWordsFor(key) {
  return [...new Set(industriesFor(key).flatMap((k) => BILL_WORDS[k] || []))];
}
const titleHas = (phrases, title) => phrases.some((w) => new RegExp(`\\b${w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'i').test(String(title || '')));

/** Bills in the register whose titles name the industry and that went to a division. */
export function candidateBills(billsIndex, key) {
  const words = billWordsFor(key);
  if (!words.length) return [];
  const exclude = industriesFor(key).flatMap((k) => BILL_EXCLUDE[k] || []);
  return (billsIndex?.bills || []).filter((b) => b?.jurisdiction === 'federal' && Number(b.divisions) > 0
    && titleHas(words, b.title) && !titleHas(exclude, b.title));
}

const STAGE_RANK = { 'Third reading': 3, 'Second reading': 2 };
// Votes on the bill itself, its amendments and its detail; procedural motions
// (business, urgency, first reading, referral) say little about a party's view.
const BILL_STAGES = /^(second reading|third reading|in committee|committee of the whole|consideration in detail)/i;
/**
 * For one bill file: the party's split at the bill's deciding division inside
 * the window, and its members' speeches on the bill. Null when the party cast
 * no recorded vote in a division dated inside the window.
 */
export function partyOnBill(bill, partyLabel, firstYear, lastYear) {
  const inWindow = (date) => { const y = Number(String(date || '').slice(0, 4)); return y >= firstYear && y <= lastYear + 1; };
  const divisions = (bill?.divisions || []).filter((d) => inWindow(d.date) && BILL_STAGES.test(String(d.stage || '')) && d.party_splits?.[partyLabel]
    && (Number(d.party_splits[partyLabel].ayes) || 0) + (Number(d.party_splits[partyLabel].noes) || 0) > 0);
  if (!divisions.length) return null;
  const deciding = [...divisions].sort((a, b) => (STAGE_RANK[b.stage] || 0) - (STAGE_RANK[a.stage] || 0) || String(b.date).localeCompare(String(a.date)))[0];
  const split = deciding.party_splits[partyLabel];
  const speeches = (bill.speeches || []).filter((s) => s?.party === partyLabel && s.slug && s.speaker).slice(0, 2)
    .map((s) => ({ slug: s.slug, speaker: s.speaker, date: s.date || '' }));
  return {
    key: bill.key, title: bill.short_title || bill.title, divisions: divisions.length,
    deciding: { date: deciding.date, stage: deciding.stage || '', ayes: Number(split.ayes) || 0, noes: Number(split.noes) || 0,
      outcome: deciding.outcome, url: /^https:\/\/theyvoteforyou\.org\.au\//.test(deciding.url || '') ? deciding.url : '' },
    speeches,
  };
}

// --- words ----------------------------------------------------------------------------

/** The page's title. */
export function flowTitle(flow, partyName = (l) => l) {
  const { kind, donor, party, state, unnamed } = flow;
  if (kind === 'pair') return `${donor.label} → ${party.label}`;
  if (kind === 'donor') return `Where ${possessive(donor.label)} money went`;
  if (kind === 'party') return `Where ${possessive(partyName(party.label))} disclosed money comes from`;
  if (kind === 'unnamed') return party ? `${unnamedDonorLabel(unnamed.donors)} → ${party.label}` : unnamedDonorLabel(unnamed.donors);
  return party ? `${industryName(state.industry)} → ${party.label}` : `Where ${industryName(state.industry).toLowerCase()} money went`;
}

/** The file a flow is read from, as a reader names it. */
const recordedIn = (flow) => (flow.jur === 'federal' ? 'The AEC returns OPAX holds record' : `OPAX’s copy of the ${flow.meta.sourceShort || flow.meta.commission || 'state register'} records`);
const span = (flow) => (flow.firstYear == null ? '' : flow.firstYear === flow.lastYear ? fyLabel(flow.firstYear) : `${fyLabel(flow.firstYear)} to ${fyLabel(flow.lastYear)}`);

/**
 * The narrative: plain sentences, each one a template over computed figures.
 * Returned as text so tests can hold every number to the data.
 */
export function narrative(flow, { partyName = (l) => l } = {}) {
  const money = shortMoney;
  const { kind, donor, party, total, count, peak, latest, unnamed } = flow;
  const out = [];
  const to = party ? partyName(party.label) : 'political parties';
  const when = span(flow);
  const yearsWithMoney = flow.dated.length;
  if (!count && !total) return ['No disclosed money matches this flow in the file.'];
  if (kind === 'pair' || kind === 'donor') {
    out.push(`${recordedIn(flow)} ${money(total)} from ${donor.label} to ${to} across ${plural(count, 'receipt')}${when ? `, from ${when}` : ''}, with money in ${plural(yearsWithMoney, 'financial year')}.`);
  } else if (kind === 'party') {
    const givers = flow.named.length + unnamed.donors;
    out.push(`${recordedIn(flow)} ${money(total)} to ${to} from ${givers === 1 ? 'the one donor' : `the ${plural(givers, 'donor')}`} on OPAX’s map, across ${plural(count, 'receipt')}${when ? `, from ${when}` : ''}.`);
  } else if (kind === 'unnamed') {
    out.push(`OPAX names organisations only. ${plural(unnamed.donors, 'donor')} it can’t confirm ${unnamed.donors === 1 ? 'is an organisation accounts' : 'are organisations account'} for ${money(total)} to ${to} across ${plural(count, 'receipt')}${when ? `, from ${when}` : ''}. They are counted here, not named.`);
  } else {
    const givers = flow.named.length + unnamed.donors;
    out.push(`${plural(givers, `${industryName(flow.state.industry).toLowerCase()} donor`)} on OPAX’s map ${givers === 1 ? 'accounts' : 'account'} for ${money(total)} to ${to} across ${plural(count, 'receipt')}${when ? `, from ${when}` : ''}.`);
  }
  if (flow.coarse) out.push(`${kind === 'unnamed' ? '' : 'OPAX names organisations only, and none of these donors is named, so they are shown as a group. '}For a group of fewer than ${AGGREGATE_FLOOR} donors this page gives the total and the count only.`);
  if (peak && yearsWithMoney > 1) {
    const latestPart = latest && latest.year !== peak.year ? ` The latest year with money is ${yearPhrase(latest.year, flow.jur, flow.electionYears)}: ${money(latest.amount)}.` : '';
    out.push(`The largest year was ${yearPhrase(peak.year, flow.jur, flow.electionYears)}: ${money(peak.amount)} across ${plural(peak.count, 'receipt')}, ${pctText(peak.amount, total)} of the flow.${latestPart}`);
  }
  if (flow.undated[1] > 0) out.push(`${plural(flow.undated[1], 'receipt')} (${money(flow.undated[0])}) ${flow.undated[1] === 1 ? 'carries' : 'carry'} no year.`);
  if ((kind === 'party' || kind === 'industry') && flow.named.length) {
    const top = flow.named.slice(0, 3).map((r) => `${r.node.label} (${money(r.total)})`);
    const lead = top.length === 1 ? top[0] : `${top.slice(0, -1).join(', ')} and ${top.at(-1)}`;
    out.push(`The largest named ${top.length === 1 ? 'giver is' : 'givers are'} ${lead}.${unnamed.donors ? ` ${unnamedDonorLabel(unnamed.donors)} account for ${money(unnamed.total)}.` : ''}`);
  }
  if ((kind === 'donor' || (kind === 'industry' && !party)) && flow.parties.length) {
    const top = flow.parties[0];
    out.push(`${flow.parties.length === 1 ? `All of it went to ${partyName(top.node.label)}.` : `Most went to ${partyName(top.node.label)}: ${money(top.total)}, ${pctText(top.total, flow.contextTotal)} of the total across ${plural(flow.parties.length, 'party', 'parties')}.`}`);
  }
  return out;
}

/** What the file calls a line, and what that means for this total. */
export function receiptTypeNote(flow) {
  if (flow.jur !== 'federal') {
    const line = STATE_LINES[flow.jur];
    return line ? `Every line in this file is a ${line.noun} as the ${flow.meta.commission || 'commission'} discloses it (${line.register}); the file holds no other kinds of receipt.` : '';
  }
  return 'The AEC labels each line on a return with a receipt type: Donation Received, Other Receipt, Subscription, Public Funding or Unspecified. OPAX’s federal export keeps the amount and the year but not that label, so this total can include receipts that are not gifts. The AEC’s detailed receipts list each line with its type.';
}

/** The disclosure rules behind each year, newest first, for the timeline. */
export function timelineRows(flow) {
  const rows = [];
  for (const [year, [amount, count]] of [...flow.years].sort((a, b) => b[0] - a[0])) {
    if (!(amount > 0)) continue;
    const row = { year, label: fyLabel(year), amount, count, period: `1 Jul ${year} – 30 Jun ${year + 1}`, election: false, threshold: '', lodged: '' };
    if (flow.jur === 'federal') {
      row.election = flow.electionYears.includes(year);
      row.threshold = federalThreshold(year);
      // From 1 January 2027 returns cover calendar years (due 25 February), so a
      // financial year from 2026 is no longer lodged as one annual return.
      row.lodged = year >= 2026 ? 'Returns move to calendar years from 1 Jan 2027' : `Annual returns due by 20 Oct ${year + 1}`;
    }
    rows.push(row);
  }
  return rows;
}

// --- markup ------------------------------------------------------------------------------

function figureHTML(value, label) {
  return `<div class="mx-figure"><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`;
}

/** One bar a year across the flow's span, the largest marked; the table beside it carries every value. */
export function trendHTML(flow, idBase = 'mx-trend') {
  if (flow.firstYear == null) return '';
  const years = [];
  for (let y = flow.firstYear; y <= flow.lastYear; y++) years.push([y, flow.years.get(y)?.[0] || 0, flow.years.get(y)?.[1] || 0]);
  const max = Math.max(...years.map((r) => r[1]), 1);
  const w = 100 / years.length;
  const bars = years.map(([y, v], i) => {
    const h = v > 0 ? Math.max(1.5, (v / max) * 100) : 0;
    const peak = flow.peak && y === flow.peak.year;
    return `<rect class="mx-bar${peak ? ' is-peak' : ''}" x="${(i * w + w * 0.14).toFixed(3)}" y="${(100 - h).toFixed(3)}" width="${(w * 0.72).toFixed(3)}" height="${h.toFixed(3)}"></rect>`;
  }).join('');
  const summary = `${fyLabel(flow.firstYear)} to ${fyLabel(flow.lastYear)}: ${plural(flow.dated.length, 'year')} with money${flow.peak ? `, the largest ${fyLabel(flow.peak.year)} at ${shortMoney(flow.peak.amount)}` : ''}.`;
  const table = `<table class="mx-table"><caption class="visually-hidden">Disclosed money by financial year</caption>
    <thead><tr><th scope="col">Financial year</th><th scope="col">Amount</th><th scope="col">Receipts</th></tr></thead>
    <tbody>${years.map(([y, v, c]) => `<tr${v > 0 ? '' : ' class="is-zero"'}><th scope="row">${esc(yearPhrase(y, flow.jur, flow.electionYears))}</th><td>${v > 0 ? esc(`$${Math.round(v).toLocaleString('en-AU')}`) : '—'}</td><td>${c ? esc(c.toLocaleString('en-AU')) : '—'}</td></tr>`).join('')}</tbody></table>`;
  return `<figure class="mx-trend" aria-labelledby="${idBase}-cap">
    <figcaption id="${idBase}-cap" class="mx-trend-cap">${esc(summary)}</figcaption>
    <svg class="mx-trend-chart" viewBox="0 0 100 100" preserveAspectRatio="none" role="img" aria-labelledby="${idBase}-cap" focusable="false">${bars}</svg>
    <div class="mx-trend-axis" aria-hidden="true"><span>${esc(fyLabel(flow.firstYear))}</span>${flow.lastYear !== flow.firstYear ? `<span>${esc(fyLabel(flow.lastYear))}</span>` : ''}</div>
    <details class="mx-disclose"><summary>Show the year-by-year table</summary>${table}</details>
  </figure>`;
}

function shareHTML(percentText, amountPart, whole, sentence) {
  const width = Math.min(100, pct(amountPart, whole));
  return `<div class="mx-share"><p class="mx-share-figure">${esc(percentText)}</p>
    <div class="mx-share-track" aria-hidden="true"><i style="width:${width.toFixed(2)}%"></i></div>
    <p class="mx-share-text">${esc(sentence)}</p></div>`;
}

function scaleHTML(flow, comparisons, partyName, matches = null) {
  const money = shortMoney;
  const shares = [];
  const r = flow.recipientShare;
  if (r) {
    const years = r.years === 1 ? fyLabel(r.first) : `${fyLabel(r.first)} to ${fyLabel(r.last)}`;
    shares.push(shareHTML(pctText(r.amount, r.whole), r.amount, r.whole, r.basis === 'returns'
      ? `of ${possessive(partyName(flow.party.label))} total receipts on its own AEC returns for ${years} (${money(r.whole)}${r.held < r.years ? `, returns held for ${r.held} of ${r.years} years` : ''}).`
      : `of all money disclosed to ${partyName(flow.party.label)} in this file for ${years} (${money(r.whole)}).`));
  }
  const d = flow.donorShare;
  if (d) shares.push(shareHTML(pctText(d.amount, d.whole), d.amount, d.whole,
    `of ${possessive(flow.donor.label)} disclosed money to parties in this file (${money(d.whole)} to ${plural(d.parties, 'party', 'parties')}).`));
  if (!r && !d && flow.parties.length > 1 && !flow.party) {
    const top = flow.parties[0];
    shares.push(shareHTML(pctText(top.total, flow.contextTotal), top.total, flow.contextTotal, `went to ${partyName(top.node.label)}, the largest of ${plural(flow.parties.length, 'recipient party', 'recipient parties')}.`));
  }
  const compare = comparisons.rows.length ? `<div class="mx-compare">
      <h3 class="mx-subhead">Comparisons</h3>
      <p class="mx-fine">${esc(comparisons.rule)}. Listed for scale only: these are separate flows, not linked to this one.</p>
      <ul class="mx-compare-list">${comparisons.rows.map((c) => `<li><a href="${esc(c.href)}">${esc(c.label)}</a><span class="mx-compare-figure">${esc(money(c.total))}${c.first ? `<small>${esc(c.first === c.last ? fyLabel(c.first) : `${fyLabel(c.first)} to ${fyLabel(c.last)}`)}</small>` : ''}</span></li>`).join('')}</ul>
    </div>` : '';
  // A party's money by industry. Not for the not-named group: its industry tags
  // would split the group back towards single donors.
  const breakdown = flow.kind === 'party' && flow.industries.length > 1
    ? `<div class="mx-compare"><h3 class="mx-subhead">By industry</h3><ul class="mx-compare-list">${flow.industries.slice(0, 5).map((i) => `<li><span>${esc(industryName(i.key))}</span><span class="mx-compare-figure">${esc(money(i.total))}<small>${esc(pctText(i.total, flow.total))}</small></span></li>`).join('')}</ul>
      <p class="mx-fine">Industry is OPAX’s tag on each donor, not a category on the return.</p></div>` : '';
  return `${shares.length ? `<div class="mx-shares">${shares.join('')}</div>` : ''}${trendHTML(flow)}${breakdown}${compare}${registersHTML(flow, matches)}`;
}

function timelineHTML(flow) {
  const rows = timelineRows(flow);
  if (!rows.length) return '';
  const federal = flow.jur === 'federal';
  const register = federal ? SOURCES.aecReceipts : { label: flow.meta.commission || 'The register', href: flow.meta.source_url };
  const item = (r) => `<li class="mx-period">
      <div class="mx-period-head"><span class="mx-period-year">${esc(r.label)}</span><span class="mx-period-amount">${esc(shortMoney(r.amount))}<small>${esc(plural(r.count, 'receipt'))}</small></span></div>
      <p class="mx-period-detail">${esc(r.period)}${r.election ? ` · includes ${r.year} election returns` : ''}${r.threshold ? ` · threshold ${r.threshold}` : ''}${r.lodged ? ` · ${r.lodged}` : ''}</p>
    </li>`;
  const SHOWN = 6;
  const items = rows.slice(0, SHOWN).map(item).join('');
  const more = rows.length > SHOWN ? `<details class="mx-disclose mx-timeline-more"><summary>All ${rows.length} years</summary>
      <ol class="mx-timeline" start="${SHOWN + 1}">${rows.slice(SHOWN).map(item).join('')}</ol></details>` : '';
  const reform = federal ? `<li class="mx-period mx-period-next">
      <div class="mx-period-head"><span class="mx-period-year">From 1 Jan 2027</span></div>
      <p class="mx-period-detail">Calendar-year returns, a $5,000 threshold and expedited disclosure of donations (see below).</p>
    </li>` : '';
  const register_link = register.href ? `<a href="${esc(register.href)}" rel="noopener" target="_blank">${esc(register.label)} ↗︎</a>` : '';
  return `<p class="mx-lede">${esc(federal
    ? 'Each row is a financial year and the disclosure rules that applied to it. OPAX holds these receipts by year, not by date, and keeps no link to each return; the AEC’s register lists every line.'
    : `Each row is a financial year. OPAX holds these ${STATE_LINES[flow.jur]?.noun || 'receipt'}s by year in its export; the commission’s register lists each one.`)}</p>
    <ol class="mx-timeline">${reform}${items}</ol>${more}
    ${register_link ? `<p class="mx-fine">Open the original: ${register_link}</p>` : ''}`;
}

function limitsHTML(flow, partyName) {
  const items = [];
  const link = (s) => `<a href="${esc(s.href)}" rel="noopener" target="_blank">${esc(s.label)} ↗︎</a>`;
  const item = (title, text, sources = []) => items.push(`<li><h3 class="mx-subhead">${esc(title)}</h3><p>${text}</p>${sources.length ? `<p class="mx-sources">${sources.map(link).join(' · ')}</p>` : ''}</li>`);
  const federal = flow.jur === 'federal';
  if (federal) {
    const ys = [...new Set(timelineRows(flow).map((r) => r.year))];
    const list = ys.length ? [...new Set(ys.map((y) => federalThreshold(y)))].length : 0;
    item('Only receipts above a threshold are listed',
      `${esc(`Returns list amounts received only above the disclosure threshold for their year, so totals here are a floor, not a ceiling.`)}${ys.length ? ` ${esc(`For the years in this flow the threshold ran from ${federalThreshold(Math.min(...ys))} (${fyLabel(Math.min(...ys))}) to ${federalThreshold(Math.max(...ys))} (${fyLabel(Math.max(...ys))})${list > 2 ? '; each year’s figure is in the timeline' : ''}.`)}` : ''}`,
      [SOURCES.aecThresholds, ...(ys.some((y) => y <= 2005) ? [SOURCES.aecOldThreshold] : [])]);
    const latest = /^\d{4}-\d{2}$/.test(String(flow.aecLatest || '')) ? Number(flow.aecLatest.slice(0, 4)) : null;
    item('Annual returns arrive months later',
      esc(`Parties lodge a financial year’s annual return within 16 weeks of 30 June, by 20 October, and the AEC publishes the returns early the next year (the 2017–18 returns on 1 February 2019, the 2024–25 returns on 2 February 2026).${latest ? ` The latest annual returns in OPAX’s data are for ${fyLabel(latest)}, so receipts after 30 June ${latest + 1} are not in them yet.` : ''}`),
      [SOURCES.aecLodging, SOURCES.aecPublished2019, SOURCES.aecPublished2026]);
    item('The rules change on 1 January 2027',
      esc('From 1 January 2027 gifts over $5,000 must be disclosed, counting a donor’s gifts to one recipient across a calendar year; returns move from financial years to calendar years, due by 25 February; and donations get expedited disclosure. The AEC says guidance on the expedited timeframes will come before then.'),
      [SOURCES.aecReform, SOURCES.aecReformDate]);
    if (flow.party) {
      const share = flow.recipientShare;
      item('Party receipts include their branches',
        esc(`A party’s state and local branches lodge their own AEC returns. Here “${flow.party.label}” covers every branch that lodged a party return under that name${share?.branches ? `: ${plural(share.branches, 'branch', 'branches')} in ${fyLabel(share.branchesYear)}` : ''}. State registers cover state parties separately, and OPAX never adds the two.`),
        [SOURCES.aecBranches, SOURCES.aecPartyReturns]);
    }
    item('What “other receipt” means',
      esc('The AEC says receipts include gifts (donations) and other receipts, such as returns on investments or sales of assets, and asks parties to tell the two apart on their returns.') +
      (flow.recipientShare && flow.recipientShare.basis === 'returns' && (flow.recipientShare.donations || flow.recipientShare.other)
        ? ` ${esc(`On ${possessive(partyName(flow.party.label))} own returns for these years, ${shortMoney(flow.recipientShare.donations)} was itemised as donations and ${shortMoney(flow.recipientShare.other)} as other receipts, out of ${shortMoney(flow.recipientShare.whole)} in total receipts. Amounts at or under the threshold need not be itemised.`)}` : ''),
      [SOURCES.aecReceiptKinds, SOURCES.aecReceipts]);
  } else {
    const meta = flow.meta;
    if (meta.threshold) item(`Only ${STATE_LINES[flow.jur]?.noun || 'donation'}s above a threshold are listed`, esc(meta.threshold), meta.source_url ? [{ label: meta.commission || 'The register', href: meta.source_url }] : []);
    if (meta.not_summed) item('State and federal figures are separate', esc(meta.not_summed));
    if (meta.coverage) item('The years this file covers', esc(`The ${meta.sourceShort || 'register'} file covers ${meta.coverage}.`));
  }
  const notNamed = flow.kind === 'unnamed' ? null : flow.unnamed;
  item('Donors OPAX doesn’t name',
    esc(`${donorsNotNamedDetail} `) + (notNamed?.donors
      ? esc(`In this view that is ${unnamedDonorLabel(notNamed.donors)}, with ${shortMoney(notNamed.total)} across ${plural(notNamed.count, 'receipt')}; their amounts are in every total above.`)
      : flow.kind === 'unnamed'
        ? esc('This page shows them as a group.')
        : esc('None of the money in this view comes from them.')));
  const top = federal ? 'The map holds the 250 largest donors by lifetime total, plus donors holding $50m or more in Commonwealth contracts and grants' : 'The map holds the 250 largest donors by lifetime total in this jurisdiction';
  item('Smaller donors are not on the map',
    esc(`${top}. The flow totals in this explanation count only those donors and leave out internal party transfers; a party’s own return totals count everything it received.`));
  // The first notes stay in view; the rest sit under one disclosure that the
  // mount opens on wide screens, so a phone reads three notes, not eight.
  const SHOWN = 3;
  const notNamedAt = items.findIndex((i) => i.includes('Donors OPAX doesn’t name'));
  if ((flow.kind === 'unnamed' || flow.coarse) && notNamedAt > 0) items.unshift(...items.splice(notNamedAt, 1));
  const rest = items.slice(SHOWN);
  return `<ul class="mx-limits">${items.slice(0, SHOWN).join('')}</ul>${rest.length ? `<details class="mx-disclose mx-limits-more">
      <summary>${esc(`${rest.length} more ${rest.length === 1 ? 'note' : 'notes'} on this record`)}</summary>
      <ul class="mx-limits">${rest.join('')}</ul></details>` : ''}`;
}

function parliamentHTML(rows, flow, partyName, words) {
  const party = flow.party;
  const items = rows.map((b) => {
    const d = b.deciding;
    const outcome = d.outcome === 'affirmative' ? 'agreed to' : d.outcome === 'negative' ? 'not agreed to' : '';
    const voted = `${party.label}: ${plural(d.ayes, 'aye', 'ayes')}, ${plural(d.noes, 'no', 'noes')}`;
    const speeches = b.speeches.length ? `<p class="mx-bill-speeches">${b.speeches.map((s) => `<a href="/doc/${encodeURIComponent(s.slug)}">${esc(s.speaker)}</a>${s.date ? ` <small>${esc(shortDate(s.date))}</small>` : ''}`).join(' · ')}</p>` : '';
    return `<li class="mx-bill">
      <a class="mx-bill-title" href="/bill/${encodeURIComponent(b.key)}">${esc(b.title)}</a>
      <p class="mx-bill-vote">${esc(voted)} · ${esc(d.stage || 'Division')}${outcome ? ` ${esc(outcome)}` : ''} · ${esc(shortDate(d.date))}${d.url ? ` · <a href="${esc(d.url)}" rel="noopener" target="_blank">Division record ↗︎</a>` : ''}</p>
      ${speeches}
    </li>`;
  }).join('');
  const quoted = words.map((w) => `“${w}”`);
  const list = quoted.length === 1 ? quoted[0] : `${quoted.slice(0, -1).join(', ')} or ${quoted.at(-1)}`;
  return `<p class="mx-caution">These are listed for context. A donation does not show that a vote or speech was influenced.</p>
    <p class="mx-fine">${esc(`Bills whose titles include ${list}, with a vote on the bill or its amendments dated ${flow.firstYear} to ${flow.lastYear + 1}. For each, ${possessive(partyName(party.label))} votes at the bill’s last reading in that time (or its last division), and up to two of its members’ speeches on the bill. Procedural motions are left out.`)}</p>
    <ul class="mx-bills">${items}</ul>`;
}

/** The app's name key for the FITS register (app.js normName). */
const normFallback = (x) => String(x || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ')
  .replace(/\b(pty|ltd|limited|the|inc|co|holdings)\b/g, '').replace(/\s+/g, ' ').trim();

/**
 * A named organisation's matches in the other registers OPAX holds: ministerial
 * diaries, lobbying registers and the Foreign Influence Transparency Scheme.
 * Counts only, from access.json and fits.json, and never for an aggregate.
 */
export function registerMatches(flow, access, fits, normName = normFallback) {
  if (!flow.donor) return null;
  const a = access?.donors?.[flow.donor.label];
  const meetings = Number(a?.meetings_total) || (Array.isArray(a?.meetings) ? a.meetings.length : 0);
  const lobbyists = Number(a?.lobbyists_total) || (Array.isArray(a?.lobbyists) ? a.lobbyists.length : 0);
  const fitsRows = fits?.by_entity?.[normName(flow.donor.label)];
  const registrations = Array.isArray(fitsRows) ? fitsRows.length : 0;
  if (!meetings && !lobbyists && !registrations) return null;
  return { meetings, lobbyists, registrations, fitsUrl: /^https:\/\//.test(fits?.meta?.source_url || '') ? fits.meta.source_url : '' };
}

function registersHTML(flow, matches) {
  if (!matches) return '';
  const parts = [
    matches.meetings ? plural(matches.meetings, 'ministerial diary meeting') : '',
    matches.lobbyists ? plural(matches.lobbyists, 'registered lobbying firm') : '',
    matches.registrations ? plural(matches.registrations, 'Foreign Influence Transparency Scheme registration') : '',
  ].filter(Boolean);
  const links = [
    flow.jur === 'federal' ? `<a href="${esc(subjectUrl('donor', flow.donor.label))}">${esc(`Listed on ${possessive(flow.donor.label)} donor page`)}</a>` : '',
    matches.registrations && matches.fitsUrl ? `<a href="${esc(matches.fitsUrl)}" rel="noopener" target="_blank">${esc('Foreign Influence Transparency Scheme register ↗︎')}</a>` : '',
  ].filter(Boolean);
  return `<div class="mx-compare"><h3 class="mx-subhead">Other registers</h3>
    <p class="mx-share-text">${esc(`${flow.donor.label} matches ${parts.join(', ')}. These are register matches, not evidence that a donation bought access.`)}</p>
    ${links.length ? `<p class="mx-fine">${links.join(' · ')}</p>` : ''}</div>`;
}

function nextStepsHTML(flow) {
  const links = [];
  const { state, donor, party, jur } = flow;
  const q = new URLSearchParams();
  if (jur !== 'federal') q.set('jur', jur);
  if (donor) q.set('focus', donor.id);
  if (party) q.set('party', party.id);
  if (state.industry) q.set('industry', state.industry);
  if (flow.kind !== 'unnamed' && !flow.coarse) links.push({ href: `/money/receipts${q.toString() ? `?${q}` : ''}`, label: 'Open these receipts in the ledger' });
  const map = new URLSearchParams();
  if (jur !== 'federal') map.set('jur', jur);
  if (donor || party) map.set('focus', (donor || party).id);
  links.push({ href: `/money${map.toString() ? `?${map}` : ''}`, label: 'See it on the money map' });
  if (donor && jur === 'federal') links.push({ href: subjectUrl('donor', donor.label), label: `${possessive(donor.label)} donor page` });
  if (party) links.push({ href: subjectUrl('party', party.label), label: `${possessive(party.label)} party page` });
  return `<ul class="mx-next">${links.map((l) => `<li><a href="${esc(l.href)}">${esc(l.label)}</a></li>`).join('')}</ul>`;
}

function sourceLine(flow) {
  const meta = flow.meta;
  const federal = flow.jur === 'federal';
  return sourceLineHTML({
    updated: meta.generated || '',
    source: federal ? 'AEC annual and election returns' : (meta.sourceShort || meta.commission || 'State register'),
    state: 'totals are a floor',
    originals: federal
      ? [SOURCES.aecRegister, SOURCES.aecReceipts, { label: 'The money map’s data (JSON)', href: '/graph/money.json?v=suppliers-1' }]
      : [{ label: meta.commission || 'The register', href: meta.source_url }, { label: 'The money map’s data (JSON)', href: `/graph/money.${flow.jur}.json` }],
    facts: [['Coverage', esc(meta.coverage || '')]],
    notes: [esc('Every figure on this page is summed from the year cells of this file and every sentence is filled from those sums. Nothing here is written by a model.')],
    licence: federal ? 'AEC Transparency Register, <a href="https://creativecommons.org/licenses/by/4.0/" rel="license noopener" target="_blank">CC BY 4.0 ↗︎</a>.' : esc(meta.licence || ''),
  });
}

/** The whole page for a resolved flow, before the parliament section loads. */
export function pageHTML(flow, { index, partyName = (l) => l, access = null, fits = null, normName = normFallback } = {}) {
  const money = shortMoney;
  const comparisons = comparableFlows(flow, index);
  const metaParts = [
    flow.party ? partyLabelHTML(flow.party.label) : '',
    esc(flow.meta.jurisdictionLabel || 'Federal'),
    esc(flow.jur === 'federal' ? 'AEC returns' : (flow.meta.sourceShort || flow.meta.commission || '')),
    span(flow) ? esc(span(flow)) : '',
  ].filter(Boolean);
  const figures = [
    figureHTML(money(flow.total), 'Disclosed'),
    figureHTML(flow.count.toLocaleString('en-AU'), flow.count === 1 ? 'Receipt' : 'Receipts'),
    flow.dated.length ? figureHTML(String(flow.dated.length), flow.dated.length === 1 ? 'Year with money' : 'Years with money') : '',
    flow.peak ? figureHTML(fyLabel(flow.peak.year), 'Largest year') : '',
  ].join('');
  const story = narrative(flow, { partyName }).map((s) => `<p>${esc(s)}</p>`).join('');
  const typeNote = receiptTypeNote(flow);
  const scale = scaleHTML(flow, comparisons, partyName, registerMatches(flow, access, fits, normName));
  const timeline = timelineHTML(flow);
  return `<article class="mx-page" aria-labelledby="mx-title">
    <div class="mx-head">
      <p class="mx-kicker">Explain this flow</p>
      <h1 class="mx-title" id="mx-title" tabindex="-1">${esc(flowTitle(flow, partyName))}</h1>
      <p class="mx-meta">${metaParts.join('<span aria-hidden="true"> · </span>')}</p>
    </div>
    <section class="mx-section mx-shows" aria-labelledby="mx-shows-h">
      <h2 class="mx-heading" id="mx-shows-h">What the record shows</h2>
      <dl class="mx-figures">${figures}</dl>
      <div class="mx-story">${story}</div>
      ${typeNote ? `<p class="mx-note">${esc(typeNote)}</p>` : ''}
      ${sourceLine(flow)}
    </section>
    ${scale.trim() ? `<section class="mx-section" aria-labelledby="mx-scale-h">
      <h2 class="mx-heading" id="mx-scale-h">Scale and context</h2>
      ${scale}
    </section>` : ''}
    ${timeline ? `<section class="mx-section" aria-labelledby="mx-time-h">
      <h2 class="mx-heading" id="mx-time-h">Timeline</h2>
      ${timeline}
    </section>` : ''}
    <section class="mx-section" aria-labelledby="mx-limits-h">
      <h2 class="mx-heading" id="mx-limits-h">What the record does and doesn’t show</h2>
      ${limitsHTML(flow, partyName)}
    </section>
    <section class="mx-section" id="mx-parliament" aria-labelledby="mx-parl-h" hidden>
      <h2 class="mx-heading" id="mx-parl-h">In parliament, for context</h2>
      <div id="mx-parliament-body"></div>
    </section>
    <section class="mx-section mx-foot" aria-labelledby="mx-next-h">
      <h2 class="mx-heading" id="mx-next-h">Keep going</h2>
      ${nextStepsHTML(flow)}
    </section>
  </article>`;
}

/** The landing page with no flow named: the largest named flows to start from. */
export function landingHTML(graph, index, jur) {
  const byId = new Map(graph.nodes.map((n) => [n.id, n]));
  const rows = graph.edges.filter(isDonation).map((e) => ({ e, d: byId.get(e.source), p: byId.get(e.target) }))
    .filter((r) => r.d?.kind === 'donor' && r.p?.kind === 'party' && !isWithheldNode(r.d, index))
    .sort((a, b) => b.e.total - a.e.total).slice(0, 6);
  return `<article class="mx-page" aria-labelledby="mx-title">
    <div class="mx-head"><p class="mx-kicker">Explain this flow</p>
      <h1 class="mx-title" id="mx-title" tabindex="-1">Explain a money flow</h1>
      <p class="mx-lede">Pick a flow on the <a href="/money">money map</a> or a donor or party page and press Explain. Or start with one of the largest named flows in this file.</p></div>
    <ul class="mx-compare-list mx-landing">${rows.map((r) => `<li><a href="${esc(explainPath({ jur, from: r.d.id, to: r.p.id }))}">${esc(`${r.d.label} → ${r.p.label}`)}</a><span class="mx-compare-figure">${esc(shortMoney(r.e.total))}</span></li>`).join('')}</ul>
  </article>`;
}

function errorHTML(message) {
  return `<article class="mx-page" aria-labelledby="mx-title"><div class="mx-head"><p class="mx-kicker">Explain this flow</p>
    <h1 class="mx-title" id="mx-title" tabindex="-1">This flow can’t be explained</h1>
    <p class="mx-lede">${esc(message)} Start from the <a href="/money">money map</a> or the <a href="/money/receipts">receipts ledger</a>.</p></div></article>`;
}

// --- mount -----------------------------------------------------------------------------

function ensureStyles(doc) {
  if (doc.querySelector('link[data-money-explain]')) return;
  const link = doc.createElement('link');
  link.rel = 'stylesheet'; link.href = STYLE_HREF; link.dataset.moneyExplain = '';
  doc.head.append(link);
}

/**
 * Mount the explanation for the address's query.
 * @param {HTMLElement} root
 * @param {{params: URLSearchParams, loadMoney: (jur: string) => Promise<any>, loadAecExtras?: () => Promise<any>,
 *   loadBillsIndex?: () => Promise<any>, loadBill?: (key: string) => Promise<any>, loadPrivacyIndex?: () => Promise<any>,
 *   onAddress?: (path: string) => void, onTitle?: (title: string) => void, partyName?: (label: string) => string,
 *   electionYears?: number[], manageFocus?: boolean}} options
 */
export function mountMoneyExplain(root, options) {
  const { params, loadMoney, loadAecExtras = async () => null, loadBillsIndex = async () => null, loadBill = async () => null,
    loadPrivacyIndex = loadDonorViewIndex, onAddress = () => {}, onTitle = () => {}, partyName = (l) => l,
    loadAccess = async () => null, loadFits = async () => null, normName = normFallback,
    electionYears = [], manageFocus = false } = options;
  let destroyed = false;
  const doc = root.ownerDocument;
  ensureStyles(doc);
  root.innerHTML = '<div class="mx-page" aria-busy="true"><p class="status" role="status">Reading the disclosed money…</p></div>';
  const settle = (html) => {
    root.innerHTML = html;
    if (manageFocus) root.querySelector('#mx-title')?.focus({ preventScroll: true });
  };
  const ready = (async () => {
    const jur = explainJurisdiction(params);
    if (!jur) { onAddress('/money/explain'); onTitle('Explain this flow'); settle(errorHTML('OPAX does not hold money data for that jurisdiction.')); return; }
    const [graph, index] = await Promise.all([loadMoney(jur), loadPrivacyIndex()]);
    if (destroyed) return;
    if (!graph?.nodes?.length) { settle(errorHTML('The disclosed-money data could not be read just now.')); return; }
    const parsed = parseExplainParams(params, graph, index);
    // The address is settled before anything is drawn: a rejected or withheld
    // identity leaves the bar here, not after the page has rendered.
    if (!parsed.ok) { onAddress(explainPath({ jur })); onTitle('Explain this flow'); settle(errorHTML(parsed.error)); return; }
    onAddress(explainPath(parsed.state));
    if (parsed.empty) { onTitle('Explain a money flow'); settle(landingHTML(graph, index, jur)); return; }
    const named = Boolean(parsed.state.from);
    const [aec, access, fits] = await Promise.all([
      jur === 'federal' ? loadAecExtras().catch(() => null) : null,
      named ? loadAccess().catch(() => null) : null,
      named ? loadFits().catch(() => null) : null,
    ]);
    if (destroyed) return;
    const flow = resolveFlow(parsed.state, graph, index, { aec, electionYears });
    onTitle(flowTitle(flow, partyName));
    settle(pageHTML(flow, { index, partyName, access, fits, normName }));
    const wide = doc.defaultView?.matchMedia?.('(min-width: 701px)');
    if (wide?.matches) root.querySelector('.mx-limits-more')?.setAttribute('open', '');
    if (parsed.withheld) root.querySelector('.mx-head')?.insertAdjacentHTML('beforeend',
      `<p class="mx-note" role="note">${esc('OPAX names organisations only, so donors it doesn’t name are shown here as a group.')}</p>`);
    await renderParliament(flow);
  })().catch(() => { if (!destroyed) settle(errorHTML('The disclosed-money data could not be read just now.')); });

  async function renderParliament(flow) {
    if (flow.jur !== 'federal' || !flow.party || flow.kind === 'unnamed' || flow.kind === 'party' || flow.firstYear == null) return;
    const key = flow.kind === 'industry' ? flow.state.industry : flow.donor?.industry;
    const words = billWordsFor(key);
    if (!words.length) return;
    const index = await loadBillsIndex().catch(() => null);
    if (destroyed) return;
    const candidates = candidateBills(index, key).sort((a, b) => String(b.status_as_of || b.introduced || '').localeCompare(String(a.status_as_of || a.introduced || ''))).slice(0, 12);
    const rows = [];
    for (const entry of candidates) {
      if (rows.length >= 3) break;
      const bill = await loadBill(entry.key).catch(() => null);
      if (destroyed) return;
      const row = bill && partyOnBill(bill, flow.party.label, flow.firstYear, flow.lastYear);
      if (row) rows.push(row);
    }
    const section = root.querySelector('#mx-parliament');
    if (!rows.length || !section) return; // a weak or empty match is left out entirely
    root.querySelector('#mx-parliament-body').innerHTML = parliamentHTML(rows, flow, partyName, words);
    section.hidden = false;
  }

  return { ready, destroy() { destroyed = true; } };
}
